import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CodEvmtK.js";const p=JSON.parse('{"title":"About Open Ink","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1790839439000}'),r={name:"about.md"};function i(s,e,l,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="about-open-ink" tabindex="-1">About Open Ink <a class="header-anchor" href="#about-open-ink" aria-label="Permalink to &quot;About Open Ink&quot;">​</a></h1><h2 id="who-made-it" tabindex="-1">Who made it <a class="header-anchor" href="#who-made-it" aria-label="Permalink to &quot;Who made it&quot;">​</a></h2><p>Open Ink is built and maintained by <a href="https://mediusware.com" target="_blank" rel="noreferrer">Mediusware</a>, a software company that designs and builds products for clients around the world. It is open source under the <a href="https://github.com/mediuswareltd/openink/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT License</a>, and anyone is welcome to use it, fork it and <a href="https://github.com/mediuswareltd/openink/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">contribute</a>.</p><h2 id="why-we-made-it" tabindex="-1">Why we made it <a class="header-anchor" href="#why-we-made-it" aria-label="Permalink to &quot;Why we made it&quot;">​</a></h2><p>Every project starts with a conversation about screens: what&#39;s on them, and how a user gets from one to the next. We needed a way to show that early, before anyone opens a design tool, and we kept running into the same problems:</p><ul><li><strong>Design tools are slow for early ideas.</strong> Laying out a dozen screens by hand takes hours, and every change to the flow means redrawing.</li><li><strong>Polished mockups get the wrong feedback.</strong> When something looks finished, people comment on fonts, colours and spacing instead of whether the flow makes sense.</li><li><strong>Static pictures don&#39;t show a flow.</strong> Stakeholders understand a product much faster when they can click through it.</li><li><strong>AI assistants are good at writing structure, but not at drawing.</strong> We wanted a format an assistant could write and a tool could check, so a first draft of a whole app takes minutes.</li></ul><p>So we made the wireframe a text file. You describe screens in YAML, Open Ink turns them into a clickable, hand-drawn prototype, and the sketchy look keeps everyone focused on structure. Because it&#39;s plain text, it lives in git next to the code, shows up in diffs and pull requests, and is easy to generate and review.</p><h2 id="what-it-s-built-on" tabindex="-1">What it&#39;s built on <a class="header-anchor" href="#what-it-s-built-on" aria-label="Permalink to &quot;What it&#39;s built on&quot;">​</a></h2><p>Open Ink stands on the shoulders of two excellent open-source projects:</p><ul><li><a href="https://github.com/rough-stuff/wired-elements" target="_blank" rel="noreferrer">wired-elements</a>: hand-drawn web components</li><li><a href="https://github.com/rough-stuff/rough" target="_blank" rel="noreferrer">RoughJS</a>: the sketchy drawing library behind them</li></ul><h2 id="get-involved" tabindex="-1">Get involved <a class="header-anchor" href="#get-involved" aria-label="Permalink to &quot;Get involved&quot;">​</a></h2><ul><li>Report a bug or ask for a feature in <a href="https://github.com/mediuswareltd/openink/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</li><li>Adding a block is one object in <code>src/render/blocks/</code>. See <a href="/openink/extending">Extending</a>.</li><li>Read the <a href="https://github.com/mediuswareltd/openink/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> for what&#39;s new.</li></ul>',12)])])}const b=t(r,[["render",i]]);export{p as __pageData,b as default};
